import {
  Mesh,
  PlaneGeometry,
  Group,
  Object3D,
  Color,
  Vector2,
  Vector3,
  FrontSide,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  mix,
  uv,
  texture,
  color,
  positionWorld,
  normalWorld,
  tslFn,
  float,
  vec2,
  vec3,
  mul,
  sub,
  step,
  smoothstep,
  pow,
  length,
  vec4,
  computed,
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{background:string,surface:string,ink:string,paper:string,accent:string,gradientStops:Array<{at:number,hex:string}>}} colors
 * @property {Object} typography
 * @property {Object} effects
 * @property {Object} textContent
 * @property {Object} scenePlacement
 */

/**
 * @typedef {Object} NodeContext
 * @property {(name:string)=>any} primitives
 * @property {{createText:(text:string,options:any)=>Object3D}} fontAtlas
 * @property {any} textureLoader
 * @property {any} glbLoader
 */

/**
 * Creates the testimonial panel node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ----- Parameters -----
  const PANEL_WIDTH = 3.4;
  const PANEL_HEIGHT = 1.9;
  const CORNER_RADIUS = 0.06;
  const BORDER_THICKNESS = 0.006;
  const PADDING = 0.5; // 2 * base unit (0.25)

  // ----- Helper to build material -----
  const buildPanelMaterial = () => {
    const uvNode = uv();
    const topColor = color('#1a1a22');
    const bottomColor = color('#111116');
    const gradient = mix(topColor, bottomColor, uvNode.y);

    const borderColor = color('#26262f');

    // Convert world‑space border thickness to UV space
    const borderU = BORDER_THICKNESS / PANEL_WIDTH;
    const borderV = BORDER_THICKNESS / PANEL_HEIGHT;

    const distX = step(uvNode.x, borderU);
    const distY = step(uvNode.y, borderV);
    const distX2 = step(1.0 - uvNode.x, borderU);
    const distY2 = step(1.0 - uvNode.y, borderV);
    const borderMask = step(0.0, distX + distY + distX2 + distY2);

    const albedo = mix(gradient, borderColor, borderMask);

    const material = new MeshStandardNodeMaterial();
    material.colorNode = albedo;
    material.roughness = 0.6;
    material.metalness = 0.2;
    material.clearcoat = 0.1;
    material.side = FrontSide;
    material.transparent = true;
    material.depthWrite = true;
    return material;
  };

  // ----- Root group -----
  const root = new Group();
  root.position.set(
    config.scenePlacement?.position?.[0] ?? 0,
    config.scenePlacement?.position?.[1] ?? 0,
    config.scenePlacement?.position?.[2] ?? 0
  );
  root.rotation.set(
    config.scenePlacement?.rotation?.[0] ?? 0,
    config.scenePlacement?.rotation?.[1] ?? 0,
    config.scenePlacement?.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scenePlacement?.scale?.[0] ?? 1,
    config.scenePlacement?.scale?.[1] ?? 1,
    config.scenePlacement?.scale?.[2] ?? 1
  );

  // ----- Panel background -----
  const panelGeometry = new PlaneGeometry(PANEL_WIDTH, PANEL_HEIGHT);
  const panelMaterial = buildPanelMaterial();
  const panelMesh = new Mesh(panelGeometry, panelMaterial);
  panelMesh.name = 'panel';
  root.add(panelMesh);

  // ----- Text helpers -----
  const createText = (text, style) => {
    // Expect ctx.fontAtlas.createText returns an Object3D ready for rendering
    const mesh = ctx.fontAtlas.createText(text, style);
    mesh.renderOrder = 1; // ensure it renders over the panel
    return mesh;
  };

  // ----- Quotation mark -----
  const quoteMarkStyle = {
    family: 'Lora',
    fontSize: 62,
    fontWeight: 600,
    letterSpacing: 0,
    lineHeight: 1,
    color: '#ff2a38',
    depth: 0.04,
    roughness: 0.5,
    metalness: 0.3,
  };
  const quoteMark = createText('“', quoteMarkStyle);
  quoteMark.position.set(
    -PANEL_WIDTH / 2 + PADDING,
    PANEL_HEIGHT / 2 - PADDING - 0.62 / 2,
    0.01
  );
  quoteMark.scale.set(1.04, 1.04, 1.04); // start overshoot for weighted‑settle
  root.add(quoteMark);

  // ----- Quote text -----
  const quoteStyle = {
    family: 'Lora',
    fontSize: 20,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.45,
    color: '#e8ecf2',
    depth: 0.03, // slight Z offset for edge definition
    maxWidth: 2.4,
  };
  const quoteText = createText(
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    quoteStyle
  );
  quoteText.position.set(
    -PANEL_WIDTH / 2 + PADDING,
    quoteMark.position.y - 0.62 / 2 - 0.25,
    0.03
  );
  root.add(quoteText);

  // ----- Accent rule (line) -----
  const ruleWidth = 0.2 * PANEL_WIDTH;
  const ruleHeight = 0.02 * PANEL_HEIGHT;
  const ruleGeometry = new PlaneGeometry(ruleWidth, ruleHeight);
  const ruleMaterial = new MeshStandardNodeMaterial();
  ruleMaterial.color = new Color('#ff2a38');
  ruleMaterial.emissive = new Color('#ff2a38');
  ruleMaterial.emissiveIntensity = 1.4;
  ruleMaterial.side = FrontSide;
  const ruleMesh = new Mesh(ruleGeometry, ruleMaterial);
  ruleMesh.position.set(
    -PANEL_WIDTH / 2 + PADDING,
    quoteText.position.y - 0.3,
    0.001
  );
  ruleMesh.position.x += ruleWidth / 2; // align left edge
  root.add(ruleMesh);

  // ----- Attribution text -----
  const attributionStyle = {
    family: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1.2,
    color: '#e8ecf2',
    maxWidth: 2.4,
  };
  const attributionText = createText('M. OKAFOR', attributionStyle);
  attributionText.position.set(
    -PANEL_WIDTH / 2 + PADDING,
    ruleMesh.position.y - ruleHeight / 2 - 0.25,
    0.001
  );
  root.add(attributionText);

  // ----- Caption text -----
  const captionStyle = {
    family: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 400,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: '#e8ecf2',
    maxWidth: 2.4,
  };
  const captionText = createText('COLLECTOR SINCE 2019', captionStyle);
  captionText.position.set(
    -PANEL_WIDTH / 2 + PADDING,
    attributionText.position.y - 0.25,
    0.001
  );
  root.add(captionText);

  // ----- Animation -----
  const timelines = [];

  // Fade‑up panel
  panelMesh.material.transparent = true;
  panelMesh.material.opacity = 0;
  root.position.y += 0.2;

  const panelTL = gsap.timeline();
  panelTL.to(
    panelMesh.material,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  panelTL.to(
    root.position,
    {
      y: root.position.y - 0.2,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  timelines.push(panelTL);

  // Weighted‑settle quote mark
  const quoteMarkTL = gsap.timeline({ delay: 0.5 });
  quoteMarkTL.to(quoteMark.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  });
  timelines.push(quoteMarkTL);

  // Store timelines for cleanup
  root.userData.__timelines = timelines;

  // ----- Cleanup -----
  root.userData.cleanup = () => {
    // Dispose geometries & materials
    panelGeometry.dispose();
    panelMaterial.dispose();
    ruleGeometry.dispose();
    ruleMaterial.dispose();

    // Assume text meshes expose dispose method
    [quoteMark, quoteText, attributionText, captionText].forEach((obj) => {
      if (obj && obj.traverse) {
        obj.traverse((child) => {
          if (child.isMesh) {
            child.geometry?.dispose();
            child.material?.dispose();
          }
        });
      }
    });

    // Kill GSAP timelines
    if (root.userData.__timelines) {
      root.userData.__timelines.forEach((tl) => tl.kill());
    }

    // Clear references
    root.traverse((c) => {
      c.userData = {};
    });
  };

  // ----- Handlers placeholder -----
  root.userData.handlers = {};

  return root;
}
